// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract Recorder {
    uint256 public lastAmount;
    uint256 public lastFrom;
    uint256 public lastTo;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastFrom = uint256(uint160(from));
        lastTo = uint256(uint160(to));
        lastAmount = amount;
        return true;
    }
}

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);

        Recorder rec = new Recorder();

        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        c.transfer(from, address(rec), tos, v);

        assertTrue(rec.lastAmount() == v);
    }
}
